function builder(){const c=current();let p=panel('1 · Identity and origin');fields(p,[['name','Character name'],['player','Player'],['species','Species / heritage'],['background','Background']]);const species='Aasimar,Dragonborn,Dwarf,Elf,Gnome,Goliath,Halfling,Human,Orc,Tiefling,Bugbear,Changeling,Firbolg,Genasi,Githyanki,Githzerai,Goblin,Hobgoblin,Kobold,Shifter,Aarakocra,Grung,Harengon,Kenku,Leonin,Lizardfolk,Loxodon,Minotaur,Owlin,Tabaxi,Tortle,Yuan-ti,Autognome,Centaur,Dhampir,Fairy,Hexblood,Kalashtar,Plasmoid,Reborn,Satyr,Thri-kreen,Triton,Warforged,Floral Dragonborn'.split(',');const backgrounds='Acolyte,Artisan,Charlatan,Criminal,Entertainer,Farmer,Guard,Guide,Hermit,Merchant,Noble,Sage,Sailor,Scribe,Soldier,Wayfarer'.split(',');for(const [k,options] of [['species',species],['background',backgrounds]]){const input=p.querySelectorAll('input')[k==='species'?2:3],list=el('datalist');list.id='builder-'+k;for(const v of options){const o=el('option');o.value=v;list.append(o)}input.setAttribute('list',list.id);p.append(list)}note(p,'Search suggestions are a starter catalog; custom and other approved options can be typed.');p=panel('2 · Classes');table(p,'classes',[['class','Class','select',classes],['subclass','Subclass'],['level','Level','number']]);calc(p,'Starting level',()=>level()===3?'Ready — level 3':level()+' — new characters start at 3');p=panel('3 · Ability scores');for(const a of abilities){let l=el('label',a);l.append(control(c.abilities[a],'base','select',[8,9,10,11,12,13,14,15]));l.append(control(c.abilities[a],'bonus','number'));calc(l,'Total',()=>score17(a));p.append(l)}calc(p,'Budget',()=>cost()+' / 36');calc(p,'Background bonuses',()=>abilities.reduce((n,a)=>n+num(c.abilities[a].bonus),0)+' (normally 3 at creation)');p=panel('4 · Equipment and origin feat');fields(p,[['origin','Origin feat'],['gp','Gold','number'],['starting','Starting equipment and approved uncommon item','area']]);p=panel('5 · Review');calc(p,'Validation',()=>{let errors=[];if(!c.name||c.name==='New character')errors.push('Name required');if(!c.species||!c.background)errors.push('Choose species and background');if(cost()!==36)errors.push('Spend exactly 36 points');if(level()!==3)errors.push('Starting level must be 3');if(new Set(c.classes.map(r=>r.class)).size!==c.classes.length)errors.push('Combine duplicate classes');if(!c.origin)errors.push('Record origin feat');return errors.join(' • ')||'Basic checks passed; DM checks prerequisites and equipment'});let b=el('button','Open character sheet');b.onclick=()=>{page=0;render()};p.append(b);note(p,'Published prerequisites, subclass features, equipment legality and background ability choices require manual review.');}

