function rollDie12(n){const a=new Uint32Array(1),limit=Math.floor(4294967296/n)*n;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%n+1}
function roll12(label,n,sides,bonus=0,mode='normal'){let dice=Array.from({length:n},()=>rollDie12(sides));let total=dice.reduce((a,b)=>a+b,0);if(mode==='advantage')total=Math.max(...dice);if(mode==='disadvantage')total=Math.min(...dice);let c=current();(c.rollHistory??=[]).unshift({label,dice,bonus,total:total+bonus,mode});c.rollHistory=c.rollHistory.slice(0,100);save();return `${label}: ${total+bonus} (${dice.join(', ')}; ${signed(bonus)})`}
const oldRender12=render;render=function(){oldRender12();let c=current();if(page===2||page===14){let p=panel('Subclass reference');note(p,'Campaign catalog suggestions; consult the published source for exact names, availability and prerequisites.');for(const r of c.classes){let l=el('label',r.class);let input=control(r,'subclass');let list=el('datalist');list.id='subclass12-'+c.classes.indexOf(r);for(const name of (catalog12[r.class]||'').split('|').filter(Boolean)){let o=el('option');o.value=name;list.append(o)}input.setAttribute('list',list.id);l.append(input,list);p.append(l)}if(page===2){p=panel('Milestone advancement');let pick=el('select');for(const name of classes){let o=el('option',name);o.value=name;pick.append(o)}let hp=el('input');hp.type='number';hp.min=1;hp.placeholder='HP gained (including CON)';let b=el('button','Apply one level');b.onclick=()=>{let r=c.classes.find(x=>x.class===pick.value),gain=Number(hp.value);if(r&&Number(r.level)>=20)return alert('Individual class cap reached.');if(c.auto14?.hp!=='Automatic'&&(!Number.isInteger(gain)||gain<1))return alert('Enter the final HP gain.');if(!confirm('Confirm DM-approved milestone and published prerequisites?'))return;if(r)r.level=Number(r.level)+1;else c.classes.push({class:pick.value,level:1});if(c.auto14?.hp!=='Automatic'){c.maxhp=num(c.maxhp)+gain;c.hp=num(c.hp)+gain;}else apply14();(c.advancementLog??=[]).push(`${pick.value} • level ${level()} • +${gain} HP`);save();render()};p.append(pick,hp,b);note(p,'HP gain is manual. Class features, spellcasting and prerequisites require review.');for(const entry of c.advancementLog||[])p.append(el('p',entry))}}
if(page===1){let p=panel('Dice roller'),mode=el('select');for(const m of ['normal','advantage','disadvantage'])mode.append(el('option',m));let result=el('p','Choose a roll.');result.setAttribute('role','status');p.append(mode,result);let g=el('div',undefined,'fields');function add(label,bonus){let b=el('button',label);b.onclick=()=>{result.textContent=roll12(label,mode.value==='normal'?1:2,20,bonus(),mode.value);history()};g.append(b)}for(const a of abilities){add(a+' check',()=>mod(a));add(a+' save',()=>saving18(a))}for(const s of Object.keys(skills))add(s,()=>skill(s));add('Initiative',()=>mod('DEX')+num(c.initiativeBonus)+effect18('Initiative'));p.append(g);let expression=el('input');expression.placeholder='2d6+3';let b=el('button','Roll expression');b.onclick=()=>{let m=expression.value.trim().match(/^(\d{1,3})d(\d{1,4})([+-]\d{1,5})?$/i);if(!m||+m[1]<1||+m[1]>100||+m[2]<2||+m[2]>1000)return alert('Use NdS+M, up to 100 dice and 1000 sides.');result.textContent=roll12(expression.value,+m[1],+m[2],Number(m[3]||0));history()};p.append(expression,b);let log=el('div');p.append(log);function history(){log.replaceChildren(el('h4','Recent rolls'));for(const r of (c.rollHistory||[]).slice(0,10))log.append(el('p',`${r.label}: ${r.total} [${r.dice.join(', ')}] ${signed(r.bonus)} • ${r.mode}`))}history()}};

